// Func001_23_00 is a deterministically generated function
// for the repomap perf fixture; it references Func002_00_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func001_23_00(a, b int) int {
	if a > b {
		return Func002_00_00(a, b) + a
	}
	return Func002_00_00(b, a) - b
}

